#include "denzic_ota_v1.h"
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

typedef struct { uint8_t image[64]; size_t used; uint32_t begin_count, write_count, abort_count, finish_count; bool fail_write; } sink_t;
static bool sink_begin(void *p, uint32_t size) { sink_t *s=p; s->used=0u; s->begin_count++; return size<=sizeof(s->image); }
static bool sink_write(void *p,const uint8_t *data,size_t length) { sink_t*s=p; s->write_count++; if(s->fail_write||s->used+length>sizeof(s->image))return false; memcpy(s->image+s->used,data,length);s->used+=length;return true; }
static bool sink_finish(void *p) { sink_t*s=p;s->finish_count++;return s->used==8u; }
static void sink_abort(void *p) { ((sink_t*)p)->abort_count++; }
static void put16(uint8_t*p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);}
static void put32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);p[2]=(uint8_t)(v>>16);p[3]=(uint8_t)(v>>24);}
static void control(uint8_t*p,uint8_t op,uint32_t size){memset(p,0,DENZIC_OTA_V1_CONTROL_BYTES);memcpy(p,DENZIC_OTA_V1_MAGIC,4u);p[4]=op;p[5]=DENZIC_OTA_V1_PROTOCOL_VERSION;put32(p+8,size);put16(p+12,4u);put16(p+14,2u);put32(p+16,0u);}
static void data_packet(uint8_t*p,uint32_t offset,const char *text){put32(p,offset);memcpy(p+4,text,4u);}
static bool expect_case(const char*name,bool actual,bool expected,const denzic_ota_v1_context_t*c,const sink_t*s){bool ok=actual==expected;printf("case=%s actual=%u expected=%u state=%u error=%u begin=%u writes=%u abort=%u finish=%u bytes=%u\n",name,actual?1u:0u,expected?1u:0u,(unsigned)c->state,(unsigned)c->last_error,(unsigned)s->begin_count,(unsigned)s->write_count,(unsigned)s->abort_count,(unsigned)s->finish_count,(unsigned)s->used);return ok;}
int main(void){uint8_t ctl[DENZIC_OTA_V1_CONTROL_BYTES],data[DENZIC_OTA_V1_DATA_HEADER_BYTES+4u],status[DENZIC_OTA_V1_STATUS_BYTES];bool all=true;sink_t s={0};denzic_ota_v1_storage_driver_t d={sink_begin,sink_write,sink_finish,sink_abort};denzic_ota_v1_context_t c;denzic_ota_v1_init(&c,d,&s,4u,2u);
 control(ctl,DENZIC_OTA_V1_OP_BEGIN,8u);all&=expect_case("positive_begin",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);data_packet(data,0u,"abcd");all&=expect_case("positive_data_0",denzic_ota_v1_handle_data(&c,data,sizeof(data)),true,&c,&s);data_packet(data,4u,"efgh");all&=expect_case("positive_data_1",denzic_ota_v1_handle_data(&c,data,sizeof(data)),true,&c,&s);control(ctl,DENZIC_OTA_V1_OP_FINISH,8u);all&=expect_case("positive_finish",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);all&=denzic_ota_v1_encode_status(&c,status,sizeof(status))==DENZIC_OTA_V1_STATUS_BYTES;
 denzic_ota_v1_reset(&c);control(ctl,DENZIC_OTA_V1_OP_BEGIN,8u);all&=expect_case("stale_begin",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);data_packet(data,4u,"efgh");all&=expect_case("stale_offset",denzic_ota_v1_handle_data(&c,data,sizeof(data)),false,&c,&s);data_packet(data,1u,"efgh");all&=expect_case("out_of_order",denzic_ota_v1_handle_data(&c,data,sizeof(data)),false,&c,&s);
 uint8_t malformed[DENZIC_OTA_V1_CONTROL_BYTES]={0};all&=expect_case("malformed_control",denzic_ota_v1_handle_control(&c,malformed,sizeof(malformed)),false,&c,&s);all&=expect_case("truncated_data",denzic_ota_v1_handle_data(&c,data,DENZIC_OTA_V1_DATA_HEADER_BYTES),false,&c,&s);
 denzic_ota_v1_reset(&c);control(ctl,DENZIC_OTA_V1_OP_BEGIN,65u);all&=expect_case("capacity_overflow",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),false,&c,&s);
 denzic_ota_v1_reset(&c);control(ctl,DENZIC_OTA_V1_OP_BEGIN,8u);all&=expect_case("interrupted_begin",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);data_packet(data,0u,"abcd");all&=expect_case("interrupted_data",denzic_ota_v1_handle_data(&c,data,sizeof(data)),true,&c,&s);s.fail_write=true;data_packet(data,4u,"efgh");all&=expect_case("transport_loss",denzic_ota_v1_handle_data(&c,data,sizeof(data)),false,&c,&s);control(ctl,DENZIC_OTA_V1_OP_ABORT,8u);all&=expect_case("abort_cleanup",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);s.fail_write=false;control(ctl,DENZIC_OTA_V1_OP_BEGIN,8u);all&=expect_case("recovery_begin_from_zero",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);data_packet(data,0u,"abcd");all&=expect_case("recovery_data_0",denzic_ota_v1_handle_data(&c,data,sizeof(data)),true,&c,&s);data_packet(data,4u,"efgh");all&=expect_case("recovery_data_1",denzic_ota_v1_handle_data(&c,data,sizeof(data)),true,&c,&s);control(ctl,DENZIC_OTA_V1_OP_FINISH,8u);all&=expect_case("recovery_finish",denzic_ota_v1_handle_control(&c,ctl,sizeof(ctl)),true,&c,&s);
 printf("COMP-REQ-558 OTA %s stm32_adapter=stm32wb_resident_loader esp_adapter=separate_rejected=1 apply=0 flash=0 reset=0 bounded_capacity=%zu\n",all?"PASS":"NO_GO",sizeof(s.image));return all?0:2;}
